test('F6-C completed snapshot independently matches all entities and evidence',function(): void{$f=reconciliationFixture();$r=reconciliationResult($f);same('PASS',$r['content']['status']);same('MATCHED',$r['content']['integrity']);same([],$r['content']['reasons']);foreach($r['content']['source_target_counts'] as $c){same($c['source'],$c['target']);same($c['source'],$c['matched']);same(0,$c['unmatched']);same(0,$c['extra']);}});
test('F6-C repeat reversed input and reviewer metadata preserve deterministic fingerprint',function(): void{$f=reconciliationFixture();$a=reconciliationResult($f);same($a,reconciliationResult($f));same($a,reconciliationResult($f,'reversed'));$report=$f['reader']->inspect(Fixture::named('baseline'));same($a['fingerprint'],$report->attest(str_repeat('a',64),'2026-10-27T10:00:00Z')->jsonSerialize()['fingerprint']);same($a['fingerprint'],$report->attest(str_repeat('b',64),'2026-10-27T11:00:00Z')->jsonSerialize()['fingerprint']);});
test('F6-C partial and failed runs never claim complete reconciliation',function(): void{foreach([Fault::None,Fault::AfterInsert] as $fault){$f=reconciliationFixture(false);(new Loader())->load(Fixture::named('baseline'),$f['sandbox'],3,null,$fault);$before=reconciliationState($f);$r=reconciliationResult($f);same('INCONCLUSIVE',$r['content']['status']);same(true,in_array('RUN_INCOMPLETE',$r['content']['reasons'],true));same($before,reconciliationState($f));}});
