test('F6-C tampered mapping provenance and payload hashes are independently rejected',function(): void{foreach(['mapping','provenance','payload'] as $fault){$f=reconciliationFixture();$key=reconciliationKey('customer','customer-a');if($fault==='mapping'){$f['setup']->execute('UPDATE f6b_mappings SET evidence_hash=? WHERE source_key=?',[str_repeat('f',64),$key]);}elseif($fault==='provenance'){$f['setup']->execute('UPDATE f6b_provenance SET envelope_hash=? WHERE source_key=?',[str_repeat('f',64),$key]);}else{reconciliationMutate($f,'customer','customer-a',static function(array $p): array{$p['status']['value']='INACTIVE';return $p;},false);}same('REVIEW_REQUIRED',reconciliationResult($f)['content']['status']);}});
test('F6-C missing provenance is not accepted from APPLIED flag',function(): void{$f=reconciliationFixture();reconciliationDelete($f,'f6b_provenance',reconciliationKey('wallet','wallet-a'));$r=reconciliationResult($f);same('REVIEW_REQUIRED',$r['content']['status']);same(true,in_array('MISSING_PROVENANCE',$r['content']['reasons'],true));});
test('F6-C stale checkpoint wrong snapshot and root tampering require review',function(): void{foreach(['checkpoint','root','run'] as $fault){$f=reconciliationFixture();$expected=$f['loaded']['checkpoint'];if($fault==='checkpoint'){$expected['cursor']=1;}elseif($fault==='root'){$f['setup']->execute('UPDATE f6b_source_snapshots SET snapshot_hash=?',[str_repeat('a',64)]);}else{$f['sandbox']->db->execute('UPDATE f6b_runs SET target_snapshot=?',[str_repeat('a',64)]);}same('REVIEW_REQUIRED',reconciliationResult($f,'baseline',$expected)['content']['status']);}});
